input.new_string:
/** Build a sprint contract from a feature's acceptance criteria */
export function buildSprintContract(feature: Feature, passingFeatureIds?: string[]): SprintContract {
  return {
    featureId: feature.id,
    featureName: feature.name,
    description: feature.description,
    acceptanceCriteria: feature.acceptanceCriteria,
    browserTestUrl: feature.browserTestUrl,
    startedAt: new Date().toISOString(),
    ...(passingFeatureIds && passingFeatureIds.length > 0 ? { passingFeatureIds } : {}),
  }
}

